       const location = hit.block.location ?? origin;
       const distance = Math.hypot(location.x-origin.x,location.y-origin.y,location.z-origin.z);
       const emission = emissionColour(hit.block);
       rgb = surfaceColour(hit,distance).map((v,a)=>Math.round(emission ? Math.min(255,v*1.15+emission[a]*0.08) : v*shade*ambient));
